#!/bin/sh
set -eu

if [ "${BEHAVIORLOCK_RESOURCE_MODE:-}" = process ]; then
  printf 'process fixture started\n' > /work/behaviorlock-process-fixture-started
  # The bounded child shell, not this wrapper, expands its loop variables.
  # shellcheck disable=SC2016
  exec prlimit --nproc=8:8 /bin/sh -c '
    index=0
    while [ "$index" -lt 32 ]; do
      /bin/sleep 5 &
      index=$((index + 1))
    done
    wait
    exit 74
  '
fi

if [ "${BEHAVIORLOCK_RESOURCE_MODE:-}" = file ]; then
  # Apply the small RLIMIT_FSIZE only after the package uid transition. A
  # container-wide limit would also constrain the root-owned strace evidence
  # file and could kill the tracer before this fixture reaches its target.
  exec prlimit --fsize=1048576:1048576 node index.js
fi

exec node index.js
